head.script:
/**************************************************************************************
* 시스템명 : 산재보상시스템
* 업무명   : 외부시스템연계민원접수처리
* 파일명   : as-is : QA0204.xml
* 파일명   : to-be : CM0101200M.xml
* 작성자   : 송왕열
* 작성일   : 2024.12.10
*
* 설 명 : 외부시스템연계민원접수처리에서 외부기관 선택에 따라 화면을 처리하고, 외부기관별 공통으로 사용되는 기능을 수행합니다.
*-------------------------------------------------------------------------------------
* 변경일         변경자         변경내역
*-------------------------------------------------------------------------------------
* 2021.10.12    HCNC_SHJ      20210812_AP_02 [HRD-NET] 직업훈련신청서 수신 처리 개발
                            	-2562 (직업훈련비용 청구서 (신))
* 2022.03.16	eds_lcs		  과업번호 : 20220316AG01  프로그램 개선 요청(정부24 휴업급여, 간병급여 청구 연계_접수프로그램)
								-민원24 -> 정부24
* 2022.06.02    eds_jsw       20220207_A2_01 - 근로자정보 변경신고 처리(신고서 IDMS 개선)
                            	- scwin.fn_IlgwalPrint 함수에 GEUNROJA_BOHEOM_NM 관련 추가 								  
* 2022.07.28	eds_lcs		  과업번호 : 20220726AA01  모바일전용앱(고객지원앱) 휴업 및 간병급여 첨부파일 개발
* 2021.10.12    HCNC_SHJ      20230125_AP_01 [HRD-NET] 직업훈련 수당 신청서 수신 처리 개발
                            	-2563 (직업훈련수당 청구서 (신))
* 2024.02.27	eds_ljy		  과업번호 : 20240222AA01  프로그램 개선 요청(정부24 One-Click 산재상담 및 신청 연계 개발) 
* 2024.12.10    송왕열         산재보상시스템 최초 프로그램 작성
*
*-------------------------------------------------------------------------------------
**************************************************************************************/

scwin.V_OebuGigwanFg;                 /* 외부기관 구분 */
scwin.V_IdmsFindRow;                  /* 처리중인 로우 */
scwin.V_SubDatasetObj;                /* 출력횟수 업데이트시 필요 */
scwin.V_IlgwalTotCnt = 0;             /* 일괄처리 총 카운트 */
scwin.V_IlgwalFailCnt = 0;            /* 일괄처리 성공 카운트 */
scwin.V_IlgwalSuccessCnt = 0;         /* 일괄처리 실패 카운트 */
scwin.V_IdmsSuccessCnt = 0;           /* idms 등록처리 성공카운트 */
scwin.V_AlertTypeFg;                  /* 0, 1, 2 */

/**************************************************************************************
 * FUNCTION 명 : scwin.onpageload
 * FUNCTION 기능설명 : 화면 Open시 Road 및 공통 파라미터 체크.
 **************************************************************************************/
scwin.onpageload = function() {
	scwin.fn_Init();
}

/**************************************************************************************
 * FUNCTION 명 : scwin.fn_Init
 * FUNCTION 기능설명 : 화면 초기화.
 **************************************************************************************/
scwin.fn_Init = function() {

	if( !com.gfn_IsNull(scwin.V_OebuGigwanFg) ) {
		scwin.fn_bizForm(scwin.V_OebuGigwanFg);
	} else {
		scwin.V_OebuGigwanFg = "2";
		div_import_1_q_qa.setSrc("/ui/sia/biz/cm/cm01/0102/CM0101201M.xml");
	}

	var filterList = "GT_CD != '1' && GT_CD != '3' && GT_CD != '4' && GT_CD != '6' && GT_CD != '8' && GT_CD != '9' && GT_CD != '11' && GT_CD != '12' && GT_CD != '15'";
	com.dataListFilter("dlt_OebuGigwan", filterList);
}

/**************************************************************************************
 * FUNCTION 명 : scwin.fn_bizForm
 * FUNCTION 기능설명 : 선택한 외부기관구분에 해당하는 민원접수화면을 출력한다.
 **************************************************************************************/
scwin.fn_bizForm = function(v_OebuGigwanFg) {

	var v_CurFormId = div_import_1_q_qa.getSrc();
	var v_ChgFormId = "/ui/sia/biz/cm/cm01/0102/CM0101200M.xml";

	scwin.V_OebuGigwanFg = v_OebuGigwanFg;

	switch( v_OebuGigwanFg ) {

		case "2"  : v_ChgFormId = "/ui/sia/biz/cm/cm01/0102/CM0101201M.xml"; break; // QA0202 - 토탈
		case "5"  : v_ChgFormId = "/ui/sia/biz/cm/cm01/0102/CM0101202M.xml"; break; // QA0210 - 정부24
		case "7"  : v_ChgFormId = "/ui/sia/biz/cm/cm01/0102/CM0101203M.xml"; break; // QA0212 - 정보공개
		case "13" : v_ChgFormId = "/ui/sia/biz/cm/cm01/0102/CM0101204M.xml"; break; // QA0220 - HRD-NET
		case "14" : v_ChgFormId = "/ui/sia/biz/cm/cm01/0102/CM0101205M.xml"; break; // QA0222 - 메타버스

		/* 고객지원센터(8), 산재병원(6), 통합의료정보시스템(EMR)(12)은 외부기관은 '기타'로 하고, 화면명은 고객지원센터, 산재병원, 통합의료정보시스템(EMR)으로 변경 */
		case "99"  : v_ChgFormId = "/ui/sia/biz/cm/cm01/0102/CM0101206M.xml"; break; // 기타
	}

	if( v_CurFormId != v_ChgFormId ) {
		div_import_1_q_qa.setSrc(v_ChgFormId);
	}
}

/**************************************************************************************
 * FUNCTION 명 : scwin.fn_IdmsJeonsongCheori
 * FUNCTION 기능설명 : IDMS 전송처리
 * 
 * param : grdObj   => 처리할 목록이 바인딩되어 있는 그리드 컴포넌트
 *		 : chkColId => 그리드 체크박스에 바인딩 되어 있는 컬럼명
 *		 : procFg   => I(idms) 또는 P(print)
 *		 : printFg  => 1(print 단건출력) -> printFg이 있는 경우 알림창(gfn_Alert) 처리를 하기 위해.
 **************************************************************************************/
scwin.fn_ReportPrintIdmsCheori = async function(grdObj, chkColId, procFg, printFg) {

	var obj = grdObj;

	var dataListId = obj.getDataList();               // 현재 binding된 dataList의 Id를 반환. (dataList속성 값)
	var dataList   = $p.getComponentById(dataListId); // id에 해당하는 컴포넌트 객체.

	scwin.V_SubDatasetObj = dataList; // id에 해당하는 컴포넌트 객체를 전역 객체에 할당.

	var v_Cnt = 0;

	for( var inx = 0; inx < dataList.getTotalRow(); inx++ ) {
		if( dataList.getCellData(inx, chkColId) != "1" ) {
			v_Cnt++;
		}
	}

	if( v_Cnt == dataList.getTotalRow() ) {
		var v_MsgArray = ["선택된 행"];
		var msg = com.message("MZZA150", v_MsgArray);
		com.gfn_Alert(msg);
		return;
	}

	/** 레포트 출력 */
	dlt_IdmsMicheoriChkMokrok.removeAll();
	dlt_IdmsReportAftCheoriInfo.removeAll();

	/** IDMS 전송 */
	dlt_IdmsJeopsuInfo.removeAll();
	dlt_IdmsSangseInfo.removeAll();

	dlt_IdmsMicheoriChkMokrokTmp.setJSON(dataList.getAllJSON(), false);

	// 처리할 데이터만 담기 위한 필터링 작업.
	dlt_IdmsMicheoriChkMokrokTmp.setColumnFilter({type:'row', colIndex:chkColId, key:"1", condition:'and'});
	dlt_IdmsMicheoriChkMokrok.setJSON(dlt_IdmsMicheoriChkMokrokTmp.getAllFilteredJSON());
	dlt_IdmsMicheoriChkMokrokTmp.clearFilter();

	/*
	 * 토탈접수건중 MINWON_DOC_CD = 8028, MINWON_DOC_FG = 4 => [보험관계 변경사항 신고서 (중소기업사업주)]
	 * dlt_IdmsCheoriDocInfo 정보에 8028_4로 매핑처리함
	 * 2011-09-22 예외처리함(토탈 요청)
	 * 토탈(2), 산재병원(6), 소액체당금 지급신청서(11), API접수(15)
	 */
	if( scwin.V_OebuGigwanFg == "2" || scwin.V_OebuGigwanFg == "6" || scwin.V_OebuGigwanFg == "11" || scwin.V_OebuGigwanFg == "13" || scwin.V_OebuGigwanFg == "15" ) {

		for( var inx = 0; inx < dlt_IdmsMicheoriChkMokrok.getTotalRow(); inx++ ) {

			var v_MinwonDocCdL = dlt_IdmsMicheoriChkMokrok.getCellData(inx, "MINWON_DOC_CD");
			var v_MinwonDocFgL = dlt_IdmsMicheoriChkMokrok.getCellData(inx, "MINWON_DOC_FG");
			var v_SjEopjongCdL = dlt_IdmsMicheoriChkMokrok.getCellData(inx, "SJ_EOPJONG_CD");
			var v_GyEopjongCdL = dlt_IdmsMicheoriChkMokrok.getCellData(inx, "GY_EOPJONG_CD");
			var v_SjSaeopFgL   = dlt_IdmsMicheoriChkMokrok.getCellData(inx, "SJ_SAEOP_FG");
			var v_GySaeopFgL   = dlt_IdmsMicheoriChkMokrok.getCellData(inx, "GY_SAEOP_FG");

			if( v_MinwonDocCdL == "8028" && v_MinwonDocFgL == "4" ) {
				dlt_IdmsMicheoriChkMokrok.setCellData(inx, "MINWON_DOC_CD", "8028_4");
			}

			if( v_MinwonDocCdL == "8044" ) {
				if( (
						v_SjSaeopFgL == "2" && ( (com.substr(v_SjEopjongCdL, 0, 1) == "4" && v_SjEopjongCdL != "40010") || v_SjEopjongCdL == "60001" )
							||
						v_GySaeopFgL == "2" && ( com.substr(v_GyEopjongCdL, 0, 2) == "41" || com.substr(v_GyEopjongCdL, 0, 2) == "42" || com.substr(v_GyEopjongCdL, 0, 4) == "0202" )
					) ) {

				} else {
					dlt_IdmsMicheoriChkMokrok.setCellData(idx, "MINWON_DOC_CD", "8044_1");
				}
			}
		}
	}

	var ozr       = "";
	var odi       = "";
	var formParam = com.gfn_GetReportParam(odi, this);
		formParam += gcm.REPORT_VAL.gv_ozColSep + "GV_JISA_NM=" + com.gfn_SsJisaName();
		formParam += gcm.REPORT_VAL.gv_ozColSep + "GV_JISA_CD=" + com.gfn_SsJisaCd();
	var odiParam  = "";
	var ds        = "";
	var prtOpt    = "";
	var title     = "";

	var v_Ozr     = "";
	var v_Odi     = "";
	var v_Title   = "";

	var v_OzRowSep = gcm.REPORT_VAL.gv_ozRowSep;

	/* 
	 * v_OzrFlag = true / false
	 * 민원서식별 PC 조회 후 정상 처리되었을 경우 v_OzrFlag = true
	 * gfn_Print 호출 시 사용되는 매개변수(ozr, odi, title, ds)를 가공하기 위해 판단하는 변수.
	 * for문이 실행되면서 각 민원서식별로 gcm.REPORT_VAL.gv_ozRowSep을 적용하여
	 * 다 건의 민원서식을 출력하기 위함.
	 */
	var v_OzrFlag = false;

	var v_Row = 0;

	for( idx = 0; idx < dlt_IdmsMicheoriChkMokrok.getTotalRow(); idx++ ) {

		var v_MinwonFg            = dlt_IdmsMicheoriChkMokrok.getCellData(idx, "MINWON_FG");
		var v_JeopsuNo            = dlt_IdmsMicheoriChkMokrok.getCellData(idx, "JEOPSU_NO");
		var v_MinwonDocCd         = dlt_IdmsMicheoriChkMokrok.getCellData(idx, "MINWON_DOC_CD");
		var v_MinwonDocNm         = dlt_IdmsMicheoriChkMokrok.getCellData(idx, "MINWON_DOC_NM");
		var v_IdmsDeungrokYn      = dlt_IdmsMicheoriChkMokrok.getCellData(idx, "IDMS_DEUNGROK_YN");
		var v_JeopsuBangsikCd     = dlt_IdmsMicheoriChkMokrok.getCellData(idx, "JEOPSU_BANGSIK_CD");
		var v_CheombufileJonjaeYn = dlt_IdmsMicheoriChkMokrok.getCellData(idx, "CHEOMBUFILE_JONJAE_YN");
		var v_YgJeopsuFg          = dlt_IdmsMicheoriChkMokrok.getCellData(idx, "YG_JEOPSU_FG");
		var v_ImsiJeopsuNo        = dlt_IdmsMicheoriChkMokrok.getCellData(idx, "IMSI_JEOPSU_NO");

		var v_Expr = "OEBUGIGWAN_FG == '" + scwin.V_OebuGigwanFg + "' &&" +
					 "MINWON_DOC_CD == '" + dlt_IdmsMicheoriChkMokrok.getCellData(idx, "MINWON_DOC_CD") + "' &&" +
					 "SY_YN == 'Y'";

		/** v_Expr에 해당하는 조건을 dlt_IdmsCheoriDocInfo에서 찾아 row를 반환. */
		scwin.V_IdmsFindRow = com.gfn_searchRow(dlt_IdmsCheoriDocInfo, v_Expr);

		var v_DocOebugigwanFg = dlt_IdmsCheoriDocInfo.getCellData(scwin.V_IdmsFindRow, "OEBUGIGWAN_FG");
		var v_DocMinwonDocCd  = dlt_IdmsCheoriDocInfo.getCellData(scwin.V_IdmsFindRow, "MINWON_DOC_CD");
		var v_DocMinwonDocNm  = dlt_IdmsCheoriDocInfo.getCellData(scwin.V_IdmsFindRow, "MINWON_DOC_NM");
			v_MinwonDocNm     = com.gfn_IsNull(v_MinwonDocNm) ? dlt_IdmsCheoriDocInfo.getCellData(scwin.V_IdmsFindRow, "MINWON_DOC_NM") : v_MinwonDocNm;
		var v_DocSrvId        = dlt_IdmsCheoriDocInfo.getCellData(scwin.V_IdmsFindRow, "SRV_ID");
		var v_DocInDs         = dlt_IdmsCheoriDocInfo.getCellData(scwin.V_IdmsFindRow, "IN_DS");
		var v_DocArgs         = dlt_IdmsCheoriDocInfo.getCellData(scwin.V_IdmsFindRow, "ARGS").split(";");
		var v_DocOutDs        = dlt_IdmsCheoriDocInfo.getCellData(scwin.V_IdmsFindRow, "OUT_DS");
		var v_DocEopmuCd      = dlt_IdmsCheoriDocInfo.getCellData(scwin.V_IdmsFindRow, "EOPMU_CD");
		var v_DocMinwonFg     = dlt_IdmsCheoriDocInfo.getCellData(scwin.V_IdmsFindRow, "MINWON_FG");
		var v_DocPcNm         = dlt_IdmsCheoriDocInfo.getCellData(scwin.V_IdmsFindRow, "PC_NM");
		var v_DocSrvUrl       = dlt_IdmsCheoriDocInfo.getCellData(scwin.V_IdmsFindRow, "SRV_URL");
		var v_DocOzrId        = dlt_IdmsCheoriDocInfo.getCellData(scwin.V_IdmsFindRow, "OZR_ID");
		var v_DocOzrFg        = dlt_IdmsCheoriDocInfo.getCellData(scwin.V_IdmsFindRow, "OZR_FG");
		var v_DocSyYn         = dlt_IdmsCheoriDocInfo.getCellData(scwin.V_IdmsFindRow, "SY_YN");

		/* 출력물 위치 */
		var v_BasePath = "/cm/cm01/0102/";

		if( scwin.V_IdmsFindRow == -1 ) {

			scwin.fn_IdmsReportAftCheori("6", v_JeopsuNo, v_MinwonDocCd, v_MinwonDocNm); // 민원서식정보 오류

		} else if( v_DocMinwonDocCd == "1022" ) {

			if( scwin.V_OebuGigwanFg == "2" && procFg == "I" ) { // idms
				scwin.fn_IdmsReportAftCheori("8", v_JeopsuNo, v_MinwonDocCd, v_MinwonDocNm); // 별도의 출력서식(이미지)이 없음
			} else if( procFg == "P" && printFg != "1") { // 리포트 다건
				scwin.fn_IdmsReportAftCheori("8", v_JeopsuNo, v_MinwonDocCd, v_MinwonDocNm); // 별도의 출력서식(이미지)이 없음
			} else if( procFg == "P" && printFg == "1") { // 리포트 단건
				com.gfn_Alert("별도의 출력서식(이미지)이 없으므로 참고하시기 바랍니다.");
				return;
			}

		} else if( v_DocMinwonDocCd=="1131" ) { // 2024.01.03 토탈에서 넘어온 API의료기관 사용신청

			if( scwin.V_OebuGigwanFg == "2" && procFg == "I" ) { // idms
				scwin.fn_IdmsReportAftCheori("0", v_JeopsuNo, v_MinwonDocCd, v_MinwonDocNm); // 별도의 출력서식(이미지)이 없음
			} else if( procFg == "P" && printFg != "1") { // 리포트 다건
				scwin.fn_IdmsReportAftCheori("8", v_JeopsuNo, v_MinwonDocCd, v_MinwonDocNm); // 별도의 출력서식(이미지)이 없음
			} else if( procFg == "P" && printFg == "1") { // 리포트 단건
				com.gfn_Alert("별도의 출력서식(이미지)이 없으므로 참고하시기 바랍니다.");
				return;
			}

		} else {

			// 모바일인 경우 토탈 첨부파일 확인 후 idms 전송
			if( v_YgJeopsuFg == "M" && !com.gfn_IsNull(v_ImsiJeopsuNo) && procFg == "I" ) {

				console.log("모바일접수문서");

				var v_IdmsErrFg = true;

				var v_IndataMapOptions = {
					"id" : 		"IN_INFO",
					"type" : 	"dataMap",
					"option" : 	{"baseNode":"map"},
					"keyInfo" : [
									{"id":"IMSI_JEOPSU_NO", "name":"IMSI_JEOPSU_NO", 	"dataType":"text"},
									{"id":"JEOPSU_NO", 		"name":"JEOPSU_NO", 		"dataType":"text"},
									{"id":"TOTAL_URL", 		"name":"TOTAL_URL", 		"dataType":"text"},
									{"id":"IDMS_FILE_URL",	"name":"IDMS_FILE_URL", 	"dataType":"text"}
								]
				};

				$p.data.create(v_IndataMapOptions);

				IN_INFO.setEmptyValue();
				IN_INFO.set("IMSI_JEOPSU_NO", dataList.getCellData(row, "IMSI_JEOPSU_NO"));
				IN_INFO.set("JEOPSU_NO", 	  dataList.getCellData(row, "JEOPSU_NO"));

				var v_OutdataMapOptions = {
					"id" : 		"OUT_INFO",
					"type" : 	"dataMap",
					"option" : 	{"baseNode":"map"},
					"keyInfo" : [{"id":"ERROR_FG", "name":"ERROR_FG", "dataType":"text"}]
				};

				$p.data.create(v_OutdataMapOptions);

				OUT_INFO.setEmptyValue();

				var sbmOptions = {
					id : 		"sbm_SaveIdmsMobileJeopsuFileCmd",
					ref : 		'data:json,[{"id":"IN_INFO",  "key":"IN_INFO" }]',
					target : 	'data:json,[{"id":"OUT_INFO", "key":"OUT_INFO"}]',
					action : 	"/cm/cm01/0101/CM0101200M_E008.do",
					mediatype : "application/json",
					method : 	"post",
					mode : 		"synchronous"
				};

				// Submission 생성
				$p.createSubmission(sbmOptions);
				sbmObj = $p.getSubmission("sbm_SaveIdmsMobileJeopsuFileCmd");

				// Submission 실행
				var e = await com.executeSubmission(sbmObj);

				if( e.responseJSON.rsMsg.statusCode != "S" ) {

					return;

				} else {
					if( OUT_INFO.get("ERROR_FG") == "false" ) {
						v_IdmsErrFg = false;
					}
				}

				if( v_IdmsErrFg ) {
					// idms 이미지를 idms서버에 등록후 해당 접수번호의 idms등로여부를 'Y'로 업데이트
					scwin.fn_UpdateIdmsDeungrokYn();
				} else {
					scwin.fn_IdmsReportAftCheori("3", v_JeopsuNo, v_MinwonDocCd, v_MinwonDocNm); // IDMS 이미지 등록처리 오류
				}

				$p.data.remove("IN_INFO");
				$p.data.remove("OUT_INFO");

			} else {

				console.log("/****************************************************************************************/");
				console.log(" * v_JeopsuNo            : " + v_JeopsuNo);
				console.log(" * v_MinwonDocCd         : " + v_MinwonDocCd);
				console.log(" * v_MinwonDocNm         : " + v_MinwonDocNm);
				console.log(" * v_IdmsDeungrokYn      : " + v_IdmsDeungrokYn);
				console.log(" * v_JeopsuBangsikCd     : " + v_JeopsuBangsikCd);
				console.log(" * v_CheombufileJonjaeYn : " + v_CheombufileJonjaeYn);
				console.log("/****************************************************************************************/");
				console.log(" * v_DocInDs             : " + v_DocInDs);
				console.log(" * v_DocArgs             : " + v_DocArgs);
				console.log(" * v_DocOutDs            : " + v_DocOutDs);
				console.log(" * v_DocEopmuCd          : " + v_DocEopmuCd);
				console.log(" * v_DocMinwonFg         : " + v_DocMinwonFg);
				console.log(" * v_DocPcNm             : " + v_DocPcNm);
				console.log(" * v_DocSrvUrl           : " + v_DocSrvUrl);
				console.log(" * v_DocOzrId            : " + v_DocOzrId);
				console.log(" * v_DocOzrFg            : " + v_DocOzrFg);
				console.log(" * v_DocSyYn             : " + v_DocSyYn);
				console.log(" * ozr                   : " + ozr);
				console.log(" * odi                   : " + odi);
				console.log(" * title                 : " + title);
				console.log("/****************************************************************************************/");


				// ---> IN_DS DataMap 생성 시작
				var v_InDsOpt = "";
					v_InDsOpt += '{"id":"'+v_DocInDs+'",';
					v_InDsOpt += '"type":"dataMap",';
					v_InDsOpt += '"option":{';
					v_InDsOpt += '"baseNode":"map"';
					v_InDsOpt += '},';
					v_InDsOpt += '"keyInfo":[';

				for( var i = 0; i < com.length(v_DocArgs); i++ ) {
					v_InDsOpt += '{';
					v_InDsOpt += '"id":"'+v_DocArgs[i]+'",';
					v_InDsOpt += '"dataType":"text"';
					v_InDsOpt += '}';

					if( i != com.length(v_DocArgs) - 1 ) {
						v_InDsOpt += ',';
					}
				}

				v_InDsOpt += ',{';
				v_InDsOpt += '"id":"PC_NM",';
				v_InDsOpt += '"dataType":"text"';
				v_InDsOpt += '}]'; // keyInfo end
				v_InDsOpt += '}';  // id end

				v_Option = JSON.parse(v_InDsOpt);
				$p.data.create(v_Option);
				// ---> IN_DS DataMap 생성 끝


				// ---> IN_DS DataMap 데이터 셋 시작
				var v_InDsData = "";
					v_InDsData += '{';

				for( var col = 0; col < com.length(v_DocArgs); col++ ) {

					v_InDsData += '"'+v_DocArgs[col] + '":"' + dlt_IdmsMicheoriChkMokrok.getCellData(idx, v_DocArgs[col]) + '"';

					if( col != com.length(v_DocArgs) - 1 ) {
						v_InDsData += ',';
					}
				}

				v_InDsData += ',"PC_NM":"' + v_DocPcNm + '"';
				v_InDsData += '}';

				var v_Data = JSON.parse(v_InDsData);
				eval(v_DocInDs).setJSON(v_Data);
				// ---> IN_DS DataMap 데이터 셋 끝


				// --> Submission ref 생성 시작
				var v_Ref = "";
				var v_InDsArr = v_DocInDs.split(";");

				for( var i = 0; i < com.length(v_InDsArr); i++ ) {

					if( i == 0 ) {
						v_Ref += "data:json,[";
					}

					v_Ref += '{';
					v_Ref += '"id":"'  + v_InDsArr[i] + '",';
					v_Ref += '"key":"' + v_InDsArr[i] + '"';
					v_Ref += '}';

					if( i < com.length(v_InDsArr) - 1 ) {
						v_Ref += ",";
					} else if( i == com.length(v_InDsArr) - 1 ) {
						v_Ref += "]";
					}
				}
				// --> Submission ref 생성 종료


				// --> Submission target 생성 시작
				var v_Target = "";
				var v_DocOutDsArr = v_DocOutDs.split(";");

				for( var i = 0; i < com.length(v_DocOutDsArr); i++ ) {

					if( i == 0 ) {
						v_Target += "data:json,[";
					}

					v_Target += '{';
					v_Target += '"id":"'  + v_DocOutDsArr[i] + '",';
					v_Target += '"key":"' + v_DocOutDsArr[i] + '"';
					v_Target += '}';

					if( i < com.length(v_DocOutDsArr) - 1 ) {
						v_Target += ",";
					} else if( i == com.length(v_DocOutDsArr) - 1 ) {
						v_Target += "]";
					}
				}
				// --> Submission target 생성 종료

				var v_Ds = "";

				var v_SbmOption = {

					id        : "sbm_" + v_DocSrvId,
					ref       : v_Ref,
					target    : v_Target,
					action    : "/cm/cm01/0101/CM0101200M_E001.do",
					method    : "post",
					mediatype : "application/json",
					mode      : "synchronous",
					submitDoneHandler : function(e) {

						var v_StatusCode = e.responseJSON.rsMsg.statusCode;
						var v_Message = e.responseJSON.rsMsg.message;

						if( v_StatusCode == "E" || (v_StatusCode == "B" && !com.gfn_IsNull(v_Message)) ) {

							v_OzrFlag = false;

							if( printFg == "1" ) {

								com.gfn_Alert(v_Message);
								return;

							} else {
								scwin.fn_IdmsReportAftCheori("1", v_JeopsuNo, v_MinwonDocCd, v_MinwonDocNm); // 서비스 조회중 오류
							}

						} else {

							var target = com.replace(v_SbmOption.target, "data:json,", "");
							var jsonKeys = Object.keys(e.responseJSON);

							var keys = jsonKeys.filter( (dataset) => ( dataset !== 'rsMsg' && !dataset.startsWith('dlt') && !dataset.startsWith('dma') ) );

							if( com.length(keys) == 0 ) {

								v_OzrFlag = false;
								scwin.fn_IdmsReportAftCheori("2", v_JeopsuNo, v_MinwonDocCd, v_MinwonDocNm); // 조회건수 없음

							} else {

								v_OzrFlag = true;

								for( var i = 0; i < keys.length; i++ ) {

									var key = keys[i];

									/*
									* true  : json array => data 형태 : [0: { key1:value1, key2:value2, key3:value3 }, 1:{ key1:value1, key2:value2, key3:value3 }]
									* false : json data  => data 형태 : { key1:value1, key2:value2, key3:value3 }
									*/
									var bArr = Array.isArray(e.responseJSON[key]) ? true : false;

									if( "undefined" === typeof this.getScopeWindow()[key] ) {

										var v_TargetArray = Object.values(JSON.parse(target));

										for( var j = 0; j < v_TargetArray.length; j++ ) {

											if( key == v_TargetArray[j].id ) {

												var v_TargetId = "";
												if( v_TargetArray[j].id == "OUT_INFO" ) {

													v_TargetId = "DS" + gcm.REPORT_VAL.gv_ozDsSecSep + idx;
													v_Ds += v_TargetId;

												} else {

													v_TargetId = v_TargetArray[j].id + gcm.REPORT_VAL.gv_ozDsSecSep + idx;
													v_Ds += v_TargetId;
												}

												if( i < keys.length - 1 ) {
													v_Ds += gcm.REPORT_VAL.gv_ozDsSep;
												}

												$p.data.remove(v_TargetId);

												var v_KeyArray;

												if( bArr ) {

													v_KeyArray = Object.keys(e.responseJSON[key][0]);
													com.create(v_TargetId, v_KeyArray);

													var v_Comp = $p.getComponentById(v_TargetId);

													for(var n = 0; n < e.responseJSON[key].length; n++ ) {
														v_Comp.setRowJSON(n, e.responseJSON[key][n]);
													}

												} else {

													v_KeyArray = Object.keys(e.responseJSON[key]);
													com.createMap(v_TargetId, v_KeyArray);

													var v_Comp = $p.getComponentById(v_TargetId);
													v_Comp.setJSON(e.responseJSON[key]);
												}

												if( v_MinwonDocCd == "2693" ) {

													v_Ozr = v_BasePath + "CM0101200R_50.ozr"; // asis /wh/WH1801R_01.ozr (oz파일 확인필요)

													if( key == "OUT_INFO_DAECHAEIRYEOK" ) {
														if( v_Comp.getTotalRow() >= 2) {
															v_Ozr = v_BasePath + "CM0101200R_50.ozr"; // asis /wh/WH1801R.ozr
														}
													}
												}
											} // key == v_TargetArray[j].id if~else end
										} // v_TargetArray.length for end
									} // typeof if~else end
								} // keys.length for end
							} // com.length(keys) == 0 if~else end
						} // e.responseJSON.rsMsg.statusCode if~else end
					} // submitDoneHandler function end
				} // v_SbmOption end

				com.executeSubmission_dynamic(v_SbmOption);

				if( v_OzrFlag ) {

					var v_JeopsuDt = dlt_IdmsMicheoriChkMokrok.getCellData(idx, "JEOPSU_DT");

					// 2024.01.20.CHS.접수일자(20240122)기준으로 서식분리 1513 : 요양비청구서 -> 간병료/이송료/보조기대 청구서
					if( v_MinwonDocCd == "1513" ) {

						if( v_JeopsuDt >= "20240122" ) {
							v_Ozr = v_BasePath + "CM0101200R_14.ozr"; // asis /wf/WF0101R.ozr
						} else {
							v_Ozr = v_BasePath + "CM0101200R_51.ozr"; // asis /wf/WF0102R.ozr
						}

					} else if( v_MinwonDocCd == "2564" ) {

						if( v_JeopsuDt >= "20240726" ) {
							v_Ozr = v_BasePath + "CM0101200R_31.ozr"; // asis /wh/WH0801R.orz
						} else {
							v_Ozr = v_BasePath + "CM0101200R_52.ozr"; // asis /wh/WH0801R_1.ozr
						}

					// 요양업무처리규정 개정에 따른 진료계획서 개정서식 반영 2024.06
					} else if( v_MinwonDocCd == "1005" || v_MinwonDocCd == "1061" ) {

						if( v_JeopsuDt >= "20240726" ) {
							v_Ozr = v_BasePath + "CM0101200R_53.ozr"; // asis /we/WE0402R.ozr
						} else {
							v_Ozr = v_BasePath + "CM0101200R_05.ozr"; // asis /we/WE0401R.ozr
						}

					}  else {
						if( v_MinwonDocCd != "2693" ) {
							v_Ozr = v_BasePath + com.UpperCase(v_DocOzrId) + ".ozr";
						}
					}

					v_Odi   = v_DocOzrId;
					v_Title = v_DocMinwonDocNm;				

					if( idx != 0 && odi != "" ) {
						ozr   += v_OzRowSep;
						odi   += v_OzRowSep;
						ds    += v_OzRowSep;
						title += v_OzRowSep;
					}

					ozr   += v_Ozr;
					odi   += v_Odi;
					ds    += v_Ds;
					title += v_Title;

					if( procFg == "P" ) {

						await scwin.fn_ChulryeokSer(v_JeopsuNo); // 출력 횟수 Update

					} else if( procFg == "I" ) {

						v_Row = dlt_IdmsJeopsuInfo.insertRow();

						dlt_IdmsJeopsuInfo.setCellData(v_Row, "JEOPSU_NO",     v_JeopsuNo);
						dlt_IdmsJeopsuInfo.setCellData(v_Row, "OEBUGIGWAN_FG", v_DocOebugigwanFg);
						dlt_IdmsJeopsuInfo.setCellData(v_Row, "MINWON_DOC_CD", v_MinwonDocCd);
						dlt_IdmsJeopsuInfo.setCellData(v_Row, "MINWON_DOC_NM", v_MinwonDocNm);
						dlt_IdmsJeopsuInfo.setCellData(v_Row, "EOPMU_CD",      v_DocEopmuCd);
						dlt_IdmsJeopsuInfo.setCellData(v_Row, "MINWON_FG",     v_DocMinwonFg);
					}
				}
			}
		} // dlt_IdmsMicheoriChkMokrok if~else end
	} // dlt_IdmsMicheoriChkMokrok for end

	if( procFg == "P" ) {

		com.gfn_Print(gcm.REPORT_VAL.G_PREVIEW, ozr, odi, formParam, odiParam, ds, prtOpt, title);

	} else if( procFg == "I" ) {

		// 추후 그리드에서 선택한 민원서식 출력 정보를 활용하여 .tif을 생성하는 공통함수를 적용 후 물리파일을 만들고 
		// idms 전송처리 로직을 구현하여, 두루모아로 파일전송하는 부분 개발필요.

		if( dlt_IdmsJeopsuInfo.getTotalRow() > 0 ) {
			await scwin.sendIdms();
		}
	}

	scwin.fn_CallIdmsReportBindingCheori(procFg);
}

/**************************************************************************************
 * FUNCTION 명 : scwin.sendIdms
 * FUNCTION 기능설명 : idms 전송처리
 **************************************************************************************/
scwin.sendIdms = async function() {

	// sbm_SendIdms
	// ref:dlt_IdmsJeopsuInfo
	// target:dlt_IdmsSangseInfo
	// /cm/cm01/0101/CM0101200M_E009.do
	// scwin.fn_CallBack
	var e = await com.executeSubmission(sbm_SendIdms);

	if( dlt_IdmsSangseInfo.getTotalRow() > 0 ) {

		for( var idx = 0;  idx < dlt_IdmsSangseInfo.getTotalRow(); idx++ ) {

			var v_JeopsuNo      = dlt_IdmsSangseInfo.getCellData(idx, "JEOPSU_NO");
			var v_MinwonDocCd   = dlt_IdmsSangseInfo.getCellData(idx, "MINWON_DOC_CD");
			var v_MinwonDocNm   = dlt_IdmsSangseInfo.getCellData(idx, "MINWON_DOC_NM");
			var v_MinwonFg      = dlt_IdmsSangseInfo.getCellData(idx, "MINWON_FG");
			var v_RtnCd         = dlt_IdmsSangseInfo.getCellData(idx, "RTN_CD");
			var v_IdmsReturnMsg = dlt_IdmsSangseInfo.getCellData(idx, "IDMS_RETURN_MSG");

			if( v_RtnCd == "0" ) {
				await scwin.fn_UpdateIdmsDeungrokYn(v_JeopsuNo, v_MinwonFg); // idms등로여부를 'Y'로 업데이트
			} else if( v_RtnCd == "3" ) {
				scwin.fn_IdmsReportAftCheori("3", v_JeopsuNo, v_MinwonDocCd, v_MinwonDocNm, v_IdmsReturnMsg); // IDMS 이미지 등록처리 오류
			}
		}
	}
}

/**************************************************************************************
 * FUNCTION 명 : scwin.fn_UpdateIdmsDeungrokYn
 * FUNCTION 기능설명 : idms 이미지를 idms서버에 등록후 해당 접수번호의 idms등로여부를 'Y'로 업데이트
 **************************************************************************************/
scwin.fn_UpdateIdmsDeungrokYn = async function(v_JeopsuNo, v_MinwonFg) {

	var v_Rtn = await qa.cfn_UpdateIdmsDeungrokYn(v_JeopsuNo, v_MinwonFg, "Y");

	if( !v_Rtn ) {
		scwin.fn_IdmsReportAftCheori("4", v_JeopsuNo, v_MinwonDocCd, v_MinwonDocNm); // 등록상태 업데이트처리 오류
	} else {
		scwin.fn_IdmsReportAftCheori("0", v_JeopsuNo, v_MinwonDocCd, v_MinwonDocNm); // IDMS 등록처리 성공
		scwin.V_IdmsSuccessCnt++;
	}
}

/**************************************************************************************
 * FUNCTION 명 : scwin.fn_IdmsReportAftCheori
 * FUNCTION 기능설명 : IDMS 등록처리중 오류나 등록성공후 처리내역 저장
 * param : v_ErrCd  0: IDMS 등록처리 성공
 *				  , 1: 리포트 조회 오류
 *				  , 2: 리포트 조회건수 없음
 *				  , 3: IDMS 이미지 등록처리 오류
 *				  , 4: 등록상태 업데이트처리 오류
 *				  , 5: IDMS 이미지 등록된 건임
 *				  , 6: dlt_IdmsCheoriDocInfo 에 민원서식정보 오류(민원서식정보 확인 필요)
 *				  , 7: 공단접수건은 idms등록처리할수 없음
 *				  , 8: 별도의 출력서식(이미지)이 없음
 **************************************************************************************/
scwin.fn_IdmsReportAftCheori = function(v_ErrCd, v_JeopsuNo, v_MinwonDocCd, v_MinwonDocNm, v_IdmsReturnMsg) {

	var v_Expr = "GT_CD == '" + v_ErrCd + "'";

	/** v_Expr에 해당하는 조건을 dlt_IdmsCheoriFgTmp에서 찾아 row를 반환. */
	var v_FindRow = com.gfn_searchRow(dlt_IdmsCheoriFgTmp, v_Expr);

	var v_Row = dlt_IdmsReportAftCheoriInfo.insertRow();

	dlt_IdmsReportAftCheoriInfo.setCellData(v_Row, "JEOPSU_NO",       v_JeopsuNo);
	dlt_IdmsReportAftCheoriInfo.setCellData(v_Row, "MINWON_DOC_CD",   v_MinwonDocCd);
	dlt_IdmsReportAftCheoriInfo.setCellData(v_Row, "MINWON_DOC_NM",   v_MinwonDocNm);
	dlt_IdmsReportAftCheoriInfo.setCellData(v_Row, "ERR_MSG_CD",      v_ErrCd);
	dlt_IdmsReportAftCheoriInfo.setCellData(v_Row, "ERR_MSG",         dlt_IdmsCheoriFgTmp.getCellData(v_FindRow, "GT_CD_NM1"));
	dlt_IdmsReportAftCheoriInfo.setCellData(v_Row, "IDMS_RETURN_MSG", v_IdmsReturnMsg);
}

/**************************************************************************************
 * FUNCTION 명 : scwin.fn_CallIdmsReportBindingCheori
 * FUNCTION 기능설명 : 
 *   1. 저장 => fn_ReportPrintIdmsCheori => fn_CallIdmsReportBindingCheori("I")
 *   2. 인쇄 => fn_ReportPrintIdmsCheori => fn_CallIdmsReportBindingCheori("P")
 * 
 * param : v_Flag => I(IDMS 저장), P(민원서식 리포트 출력)
 **************************************************************************************/
scwin.fn_CallIdmsReportBindingCheori = async function(v_Flag) {

	if( v_Flag == "P" ) {

		if( dlt_IdmsReportAftCheoriInfo.getTotalRow() > 0 ) {
			var v_Param = "v_Flag=P";
			com.gfn_Dialog("/ui/sia/biz/cm/cm01/0102/CM0101201P.xml", v_Param, 900, 500, "민원서류출력오류목록"); // asis QA0205.xml
		}

	} else if( v_Flag == "I" ) {

		var v_TotCnt = dlt_IdmsMicheoriChkMokrok.getTotalRow(); 

		if( scwin.V_AlertTypeFg == "A" ) {

			var msg  = "총 처리건 수 : " + scwin.V_IlgwalTotCnt     + "건\n";
				msg += "성공 : "        + scwin.V_IlgwalSuccessCnt + "건(" + scwin.V_IlgwalSuccessCnt + "건 중 " + scwin.V_IdmsSuccessCnt + "건 IDMS등록처리)\n";
				msg += "실패 : "        + scwin.V_IlgwalFailCnt    + "건";

			await com.gfn_Alert(msg);

		} else if( scwin.V_AlertTypeFg == "B" ) {

			await com.gfn_Alert("총 " + v_TotCnt + "건중 " + scwin.V_IlgwalSuccessCnt + "건을 저장하고 \n" + scwin.V_IdmsSuccessCnt + "건을 IDMS등록처리 했습니다.");

		} else if( scwin.V_AlertTypeFg == "C" ) {

			await com.gfn_Alert("총 " + v_TotCnt + "건중 " + scwin.V_IdmsSuccessCnt + "건을 IDMS등록처리 했습니다.");
		}

		if( com.dataListFilter("dlt_IdmsReportAftCheoriInfo", "ERR_MSG_CD != '0' && ERR_MSG_CD != '5'").length > 0 ) {

			var v_Param = "v_Flag=I";
			com.gfn_Dialog("/ui/sia/biz/cm/cm01/0102/CM0101201P.xml", v_Param, 900, 500, "IDMS등록오류목록"); // asis QA0205.xml

			dlt_IdmsReportAftCheoriInfo.clearFilter();
		}

		if( scwin.V_IlgwalSuccessCnt > 0 || scwin.V_IdmsSuccessCnt > 0 ) {
			div_import_1_q_qa.scope.scwin.btn_Johoe_onclick();
		}

		scwin.V_IdmsSuccessCnt = 0; // idms 등록처리 성공 카운트 초기화.
	}
}

/**************************************************************************************
 * FUNCTION 명 : scwin.fn_ChulryeokSer
 * FUNCTION 기능설명 : 출력 횟수 업데이트
 **************************************************************************************/
scwin.fn_ChulryeokSer = async function(v_JeopsuNo) {

	$p.data.remove("dma_JeopsuInfo");
	com.createMap("dma_JeopsuInfo",  ["JEOPSU_NO"]);

	var dataMap = $p.getComponentById("dma_JeopsuInfo");
	dataMap.set("JEOPSU_NO", v_JeopsuNo);

	var v_SbmOption = {
		"id"        : "sbm_UpdateChulryeokSerInfoCmd",
		"ref"       : 'data:json,{"id":"dma_JeopsuInfo","key":"dma_JeopsuInfo"}',
		"action"    : "/cm/cm01/0101/CM0101200M_E003.do",
		"mode"      : "synchronous",
		"isShowMeg" : false
	};

	var v_SbmObj = $p.getSubmission("sbm_UpdateChulryeokSerInfoCmd");
	if(v_SbmObj !== null) {
		$p.deleteSubmission("sbm_UpdateChulryeokSerInfoCmd");
	}

	com.createSubmission(v_SbmOption);
	v_SbmObj = $p.getSubmission("sbm_UpdateChulryeokSerInfoCmd");

	// UpdateChulryeokSerInfoCmd
	// sbm_UpdateChulryeokSerInfoCmd
	// ref:dma_JeopsuInfo
	// target:
	// /cm/cm01/0101/CM0101200M_E003.do
	// scwin.fn_CallBack
	var e = await com.executeSubmission(v_SbmObj);

	if( e.responseJSON.rsMsg.statusCode != 'S' ) {

		console.log("message", e.responseJSON.rsMsg.message);
		console.log("statusCode", e.responseJSON.rsMsg.statusCode);
		console.log("출력횟수 업데이트 처리중 오류");
		return false;

	} else {

		var v_ChulryeokSer = 0;

		var v_Expr = "JEOPSU_NO == '" + v_JeopsuNo + "'";
		var v_FindRow = com.gfn_searchRow(scwin.V_SubDatasetObj, v_Expr);

		if( v_FindRow != -1 ) {

			v_ChulryeokSer = scwin.V_SubDatasetObj.getCellData(v_FindRow, "CHULRYEOK_SER");

			if( com.gfn_IsNull(v_ChulryeokSer) ) {
				v_ChulryeokSer = 1;
			} else {
				v_ChulryeokSer = com.toInteger(scwin.V_SubDatasetObj.getCellData(v_FindRow, "CHULRYEOK_SER")) + 1;
			}

			scwin.V_SubDatasetObj.setCellData(v_FindRow, "CHULRYEOK_SER", v_ChulryeokSer + " 회");
		}
	}
}

/* 
 * (본인부담치료비) 모바일 데이터 송신 
 *  AGA930MT_IFR, BZA720MT_IFR   -> QAA700MT_IFS 
 *  OZ scheduler 호출  -> 파일 경로 : "/idms/IN_NOZNID_001/"
 * 						  "           "/idms_backup/IN_NOZNID_001/"  에 저장 						  
 *	param1 : UPDATE_YN  Y - UPDATE, N - INSERT 
 *  param2 : grdObj  Grid데이터셋 
 *  param3 : row    INSERT 시 Row 
 *  return : 없음 
 */
scwin.fn_MobileChumbuFileDataSongsin = function(UPDATE_YN, grdObj, row) {

	dma_BMobileCheombuFile.setEmptyValue();

	// update 여부 확인  
	if( UPDATE_YN == "N" ) {

		dma_BMobileCheombuFile.set("JEOPSU_NO", dlt_IdmsMicheoriChkMokrok.getCellData(row, "JEOPSU_NO"));
		dma_BMobileCheombuFile.set("DAMDANGJA_ID", dlt_IdmsMicheoriChkMokrok.getCellData(row, "DAMDANGJA_ID"));
		dma_BMobileCheombuFile.set("UPDATE_YN", "N");

	}

	var srvId		 = "MobileSincheongseoSendCmd";
	var strURL		 = "kcw.q.qa.cmd.MobileSincheongseoSendCmd.do";
	var strinDsList	 = "IN_INFO=dma_BMobileCheombuFile";
	var stroutDsList = ""; 
	var strArgument	 = "";
	var strCallback  = "fn_CallBack";

	var rtnCall = com.gfn_CallService(srvId, strURL, strinDsList, stroutDsList, strArgument, strCallback, true, true, false);

	return rtnCall;
}

/**************************************************************************************
 * FUNCTION 명 : scwin.fn_SetDisabled
 * FUNCTION 기능설명 : 미접수, IDMS미처리 선택 시 [담당자반영, 담당자조회, 저장, 인쇄] 버튼 활성/비활성 처리.
 * param : v_DisabledFg("0" / "1" / "")
 * scwin.V_OebuGigwanFg
 *       2:토탈
 *       5:정부24
 *       7:정보공개
 *       13:HRD-NET
 *       14:메타버스
 *       99:기타
 **************************************************************************************/
scwin.fn_SetBtnDisabled = function(v_DisabledFg) {

	div_import_1_q_qa.getWindow().btn_Save.setDisabled(true);
	div_import_1_q_qa.getWindow().btn_Print.setDisabled(true);

	if( scwin.V_OebuGigwanFg == "2" || scwin.V_OebuGigwanFg == "5" || scwin.V_OebuGigwanFg == "13" ) {

		div_import_1_q_qa.getWindow().btn_DamdangjaJohoe.setDisabled(true);
		div_import_1_q_qa.getWindow().btn_DamdangjaBanyeong.setDisabled(true);

		if( v_DisabledFg == "0" ) {
			div_import_1_q_qa.getWindow().btn_Save.setDisabled(false);                // [저장]
			div_import_1_q_qa.getWindow().btn_Print.setDisabled(false);               // [인쇄]
			div_import_1_q_qa.getWindow().btn_DamdangjaJohoe.setDisabled(false);      // [담당자조회]
			div_import_1_q_qa.getWindow().btn_DamdangjaBanyeong.setDisabled(false);   // [담당자반영]
		} else if( v_DisabledFg == "1" ) {
			div_import_1_q_qa.getWindow().btn_Save.setDisabled(false);                // [저장]
			div_import_1_q_qa.getWindow().btn_Print.setDisabled(false);               // [인쇄]
		}

	} else if( scwin.V_OebuGigwanFg == "7" ) { // 정보공개

		if( v_DisabledFg == "0" ) {
			div_import_1_q_qa.getWindow().btn_Save.setDisabled(false);                // [저장]
			div_import_1_q_qa.getWindow().btn_Print.setDisabled(false);               // [인쇄]
		} else if( v_DisabledFg == "1" ) {
			div_import_1_q_qa.getWindow().btn_Save.setDisabled(false);                // [저장]
			div_import_1_q_qa.getWindow().btn_Print.setDisabled(true);                // [인쇄]
		}

	} else if( scwin.V_OebuGigwanFg == "14" ) { // 메타버스

		div_import_1_q_qa.getWindow().btn_DamdangjaBanyeong.setDisabled(true);

		if( v_DisabledFg == "0" ) {
			div_import_1_q_qa.getWindow().btn_Save.setDisabled(false);                // [저장]
			div_import_1_q_qa.getWindow().btn_DamdangjaBanyeong.setDisabled(false);   // [담당자반영]
		} else if( v_DisabledFg == "1" ) {
			div_import_1_q_qa.getWindow().btn_Save.setDisabled(false);                // [저장]
		}

	} else if( scwin.V_OebuGigwanFg == "99" ) { // 기타

		div_import_1_q_qa.getWindow().btn_DamdangjaBanyeong.setDisabled(true);       // [담당자반영]

		if( v_DisabledFg == "0" ) {
			div_import_1_q_qa.getWindow().btn_Print.setDisabled(false);              // [인쇄]]
		}
	}
}

/**************************************************************************************
 * FUNCTION 명 : scwin.fn_GridKeyCtr
 * FUNCTION 기능설명 : grid cell edit - keyCode Controll
 **************************************************************************************/
scwin.fn_GridKeyCtr = function(e) {

	var v_KeyCode = e.keyCode;

	// F2
	if( v_KeyCode == "113" ) {
		var row = div_import_1_q_qa.getWindow().scwin.V_DataList.getRowPosition();
		div_import_1_q_qa.getWindow().scwin.V_Obj.setFocusedCell(row, "DAMDANGJA_ID", true);
		return;
	}
}
